package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables for hardcoded passwords
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if variable name suggests a password/secret
    password_names := {"password", "secret", "token", "api_key", "credential", "auth", "passwd", "key"}
    contains_lower(var.name, password_names[_])

    # Check if value is a string literal (not a reference)
    var.value.ir_type == "String"

    # Exclude common non-sensitive patterns (e.g., booleans, paths, placeholders)
    not is_safe_value(var.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded password - Secrets should not be stored directly in code. (CWE-259)"
    }
}

