# Helper function to check if string contains any of the given substrings (case-insensitive)
contains_lower(str, substr) {
    regex.match(sprintf("(?i).*%s.*", [substr]), str)
}

# Helper function to exclude safe values (e.g., placeholders, booleans, empty strings, non-sensitive strings)
is_safe_value(value) {
    # Exclude placeholders like "changeme", "password", "secret"
    safe_patterns := {"changeme", "password", "secret", "placeholder", "none", "null", "true", "false"}
    contains_lower(value, safe_patterns[_])
} else {
